peer_setup:
$__theme: peer.m2-define-light-theme((
  color: (
    primary: peer.m2-define-palette(peer.$m2-indigo-palette),
    accent: peer.m2-define-palette(peer.$m2-pink-palette, A200, A100, A400),
    warn: peer.m2-define-palette(peer.$m2-red-palette),
  ),
  typography: peer.m2-define-typography-config(),
  density: 0,
));

